Here is the commit message:
crypto: jitterentropy - replace long-held spinlock with mutex

jent_kcapi_random() serializes the shared jitterentropy state, but it
currently holds a spinlock across the jent_read_entropy() call. That
path performs expensive jitter collection and SHA3 conditioning, so
parallel readers can trigger stalls as contending waiters spin for
the same lock.

To prevent non-preemptible lock hold, replace rng->jent_lock with a
mutex so contended readers sleep instead of spinning on a shared lock
held across expensive entropy generation.

Fixes: bb5530e40824 ("crypto: jitterentropy - add jitterentropy RNG")
Reported-by: Yifan Wu <yifanwucs@gmail.com>
Reported-by: Juefei Pu <tomapufckgml@gmail.com>
Reported-by: Yuan Tan <yuantan098@gmail.com>
Suggested-by: Xin Liu <bird@lzu.edu.cn>
Signed-off-by: Haixin Xu <jerryxucs@gmail.com>
Reviewed-by: Stephan Mueller <smueller@chronox.de>
Signed-off-by: Herbert Xu <herbert@gondor.apana.org.au>

Here is the root cause:
The bug is a performance and livelock issue caused by holding a spinlock (`rng->jent_lock`) across the expensive `jent_read_entropy()` call in `jent_kcapi_random()`. Spinlocks are intended for short, non-sleeping critical sections; however, `jent_read_entropy()` performs jitter collection and SHA3 conditioning, which can take a long time. When multiple readers try to access the shared jitterentropy state concurrently, contending threads spin on the lock, wasting CPU cycles and potentially causing system stalls. The fix replaces the spinlock with a mutex, which allows contending threads to sleep while waiting, thus avoiding busy-waiting.

Here is the patch:
 #include <linux/kernel.h>
 #include <linux/module.h>
+#include <linux/mutex.h>
 #include <linux/slab.h>
 #include <linux/time.h>

 struct jitterentropy {
-	spinlock_t jent_lock;
+	struct mutex jent_lock;
 	struct rand_data *entropy_collector;
 	struct crypto_shash *tfm;

 static void jent_kcapi_cleanup(struct crypto_tfm *tfm)
 {
 	struct jitterentropy *rng = crypto_tfm_ctx(tfm);

-	spin_lock(&rng->jent_lock);
+	mutex_lock(&rng->jent_lock);

 	if (rng->sdesc) {
 		shash_desc_zero(rng->sdesc);
 		kfree(rng->sdesc);
 	}
 	rng->sdesc = NULL;

 	if (rng->tfm)
 		crypto_free_shash(rng->tfm);
 	rng->tfm = NULL;

 	if (rng->entropy_collector)
 		jent_entropy_collector_free(rng->entropy_collector);
 	rng->entropy_collector = NULL;
-	spin_unlock(&rng->jent_lock);
+	mutex_unlock(&rng->jent_lock);
 }

 static int jent_kcapi_init(struct crypto_tfm *tfm)
 {
 	struct jitterentropy *rng = crypto_tfm_ctx(tfm);
 	struct crypto_shash *hash;
 	struct shash_desc *sdesc;
 	int size, ret = 0;

-	spin_lock_init(&rng->jent_lock);
+	mutex_init(&rng->jent_lock);

 	/* Use SHA3-256 as conditioner */
 	hash = crypto_alloc_shash(JENT_CONDITIONING_HASH, 0, 0);
 	if (IS_ERR(hash)) {
 		pr_err("Cannot allocate conditioning digest\n");
 		return PTR_ERR(hash);
 	}
 	rng->tfm = hash;

 	size = sizeof(struct shash_desc) + crypto_shash_descsize(hash);
 	sdesc = kmalloc(size, GFP_KERNEL);
 	if (!sdesc) {
 		ret = -ENOMEM;
 		goto err;
 	}

 	sdesc->tfm = hash;
 	crypto_shash_init(sdesc);
 	rng->sdesc = sdesc;

 	rng->entropy_collector =
 		jent_entropy_collector_alloc(CONFIG_CRYPTO_JITTERENTROPY_OSR, 0,
 					     sdesc);
 	if (!rng->entropy_collector) {
 		ret = -ENOMEM;
 		goto err;
 	}

-	spin_lock_init(&rng->jent_lock);
 	return 0;

 err:
 	jent_kcapi_cleanup(tfm);
 	return ret;
 }

 static int jent_kcapi_random(struct crypto_rng *tfm,
 			     const u8 *src, unsigned int slen,
 			     u8 *rdata, unsigned int dlen)
 {
 	struct jitterentropy *rng = crypto_rng_ctx(tfm);
 	int ret = 0;

-	spin_lock(&rng->jent_lock);
+	mutex_lock(&rng->jent_lock);

 	ret = jent_read_entropy(rng->entropy_collector, rdata, dlen);

 	if (ret == -3) {
 		/* Handle permanent health test error */
 		/*
 		 * If the kernel was booted with fips=1, it implies that
 		 * the entire kernel acts as a FIPS 140 module. In this case
 		 * an SP800-90B permanent health test error is treated as
 		 * a FIPS module error.
 		 */
 		if (fips_enabled)
 			panic("Jitter RNG permanent health test failure\n");

 		pr_err("Jitter RNG permanent health test failure\n");
 		ret = -EFAULT;
 	} else if (ret == -2) {
 		/* Handle intermittent health test error */
 		pr_warn_ratelimited("Reset Jitter RNG due to intermittent health test failure\n");
 		ret = -EAGAIN;
 	} else if (ret == -1) {
 		/* Handle other errors */
 		ret = -EINVAL;
 	}

-	spin_unlock(&rng->jent_lock);
+	mutex_unlock(&rng->jent_lock);

 	return ret;
 }



